var liveFeedSource=null,liveFeedRowLimit=50,liveFeedStageLabels={delivery:"Delivery",open:"Open",lure:"Lure",cloak:"Cloak",verify:"Verify",credential:"Credential",capture:"Capture",replay:"Replay",report:"Report",initialization:"Initialization",webauthn:"WebAuthn"};function liveFeedStageLabel(e){return liveFeedStageLabels[e]||e||""}function liveFeedRow(e){var t=(e=e||{}).timestamp?moment.utc(e.timestamp).local().format("h:mm:ss a"):"",i=(e.techniques||[]).join(", ");return"<tr><td>"+escapeHtml(t)+"</td><td>"+escapeHtml(liveFeedStageLabel(e.stage))+"</td><td>"+escapeHtml(e.outcome||"")+"</td><td>"+escapeHtml(i)+"</td><td>"+escapeHtml(e.rid||"")+"</td></tr>"}function liveFeedAppend(e){var t=$("#liveFeedBody");if(0!==t.length){$("#liveFeedEmpty").remove(),t.prepend(liveFeedRow(e));var i=t.find("tr");i.length>liveFeedRowLimit&&i.slice(liveFeedRowLimit).remove()}}function startLiveFeed(e){"undefined"!=typeof EventSource&&(stopLiveFeed(),(liveFeedSource=new EventSource("/campaigns/"+e+"/feed")).onmessage=function(e){var t;try{t=JSON.parse(e.data)}catch(e){return}liveFeedAppend(t)},liveFeedSource.onerror=function(){})}function stopLiveFeed(){liveFeedSource&&(liveFeedSource.close(),liveFeedSource=null)}$(window).on("beforeunload",(function(){stopLiveFeed()}));